#!/usr/bin/env python3
"""Emit one Linux TCP cumulative-counter event for UC-1.1.51."""
import json
import time
from pathlib import Path


def read_section(path, section):
    rows = [line.split() for line in Path(path).read_text(encoding="ascii").splitlines() if line.startswith(section + ":")]
    if len(rows) < 2 or len(rows[-2]) != len(rows[-1]):
        raise RuntimeError(f"missing or malformed {section} rows in {path}")
    return dict(zip(rows[-2][1:], rows[-1][1:]))


tcp = read_section("/proc/net/snmp", "Tcp")
tcp_ext = read_section("/proc/net/netstat", "TcpExt")
event = {
    "collection_epoch": int(time.time()),
    "boot_id": Path("/proc/sys/kernel/random/boot_id").read_text(encoding="ascii").strip(),
    "tcp_retrans_segs_total": int(tcp["RetransSegs"]),
    "tcp_original_data_segs_total": int(tcp_ext["TCPOrigDataSent"]),
}
print(json.dumps(event, separators=(",", ":"), sort_keys=True), flush=True)
